101	/* ── DNS 兜底：openspeech.bytedance.com 板端解析失败（2026-08-12）──
102	 * mbedtls_net_connect 返回 MBEDTLS_ERR_NET_UNKNOWN_HOST(-0x52) =
103	 * getaddrinfo 失败（域名带 3 级 CNAME 链 bytedns1→cdngslb→queniuiq，
104	 * 板端 DNS 客户端解析不过，UI 语音 PTT 0 字节根因之一）；回退直连
105	 * 已知 CDN IP（SNI 仍用真实域名 mbedtls_ssl_set_hostname，证书/路由
106	 * 按 SNI 走不受影响）。IP 来自 PC 解析 openspeech.bytedance.com 的
107	 * A 记录（bytedance CDN，长期稳定）。 */
108	static const char* const s_asr_ip_fallback[] = {
109	    "183.240.127.14", "120.233.0.88", "183.240.127.16",
110	    "120.233.0.89",   "120.233.0.90", "183.240.127.15",
111	    NULL
112	};
