114	static int asr_net_connect_fallback(asr_tls_ctx_t* ctx,
115	    const char* host, const char* port)
116	{
117	    int ret = mbedtls_net_connect(&ctx->net, host, port,
118	        MBEDTLS_NET_PROTO_TCP);
119	
120	    if (ret != MBEDTLS_ERR_NET_UNKNOWN_HOST) {
121	        return ret;   /* 成功或非 DNS 类错误：原样返回 */
122	    }
123	
124	    syslog(LOG_WARNING, "[volc_asr] DNS fail %s, try IP fallback\n", host);
125	
126	    for (int i = 0; s_asr_ip_fallback[i]; i++) {
127	        ret = mbedtls_net_connect(&ctx->net, s_asr_ip_fallback[i], port,
128	            MBEDTLS_NET_PROTO_TCP);
129	        if (ret == 0) {
130	            syslog(LOG_INFO, "[volc_asr] IP fallback connected: %s\n",
131	                s_asr_ip_fallback[i]);
132	            return 0;
133	        }
134	    }
135	
136	    return ret;
137	}
