140	
141	static int asr_tls_connect(asr_tls_ctx_t* ctx,
142	    const char* host, const char* port)
143	{
144	    int ret;
145	
146	    mbedtls_ssl_init(&ctx->ssl);
147	    mbedtls_ssl_config_init(&ctx->cfg);
148	    mbedtls_net_init(&ctx->net);
149	    mbedtls_ctr_drbg_init(&ctx->ctr_drbg);
150	
151	    const char* pers = "volc_asr";
152	
153	    ret = mbedtls_ctr_drbg_seed(&ctx->ctr_drbg, asr_entropy_func,
154	        NULL, (const unsigned char*)pers,
155	        strlen(pers));
156	    if (ret != 0) {
157	        syslog(LOG_ERR, "[%s] ctr_drbg_seed: -0x%04x\n", TAG, -ret);
158	        return -EIO;
159	    }
160	
161	    /* If proxy is enabled, open a CONNECT tunnel first */
162	    if (http_proxy_is_enabled()) {
163	        int port_num = atoi(port);
164	        int tunnel_fd = proxy_open_tunnel(host, port_num, 30000);
165	
166	        if (tunnel_fd < 0) {
167	            syslog(LOG_ERR, "[%s] proxy tunnel failed\n", TAG);
168	            return -ECONNREFUSED;
169	        }
170	
171	        ctx->net.fd = tunnel_fd;
172	        syslog(LOG_INFO, "[%s] Using proxy tunnel fd=%d for %s:%s\n",
173	            TAG, tunnel_fd, host, port);
174	    } else {
175	        ret = asr_net_connect_fallback(ctx, host, port);
176	        if (ret != 0) {
177	            syslog(LOG_ERR, "[%s] net_connect %s:%s: -0x%04x\n",
178	                TAG, host, port, -ret);
179	            return -ECONNREFUSED;
180	        }
181	    }
182	
183	    mbedtls_net_set_block(&ctx->net);
184	    if (ctx->net.fd >= 0) {
185	        struct timeval tv = { .tv_sec = 30, .tv_usec = 0 };
186	
187	        setsockopt(ctx->net.fd, SOL_SOCKET, SO_RCVTIMEO,
188	            &tv, sizeof(tv));
189	    }
190	
191	    ret = mbedtls_ssl_config_defaults(&ctx->cfg,
192	        MBEDTLS_SSL_IS_CLIENT,
193	        MBEDTLS_SSL_TRANSPORT_STREAM,
194	        MBEDTLS_SSL_PRESET_DEFAULT);
195	    if (ret != 0) {
196	        return -EIO;
197	    }
198	
199	    mbedtls_ssl_conf_min_tls_version(&ctx->cfg,
200	        MBEDTLS_SSL_VERSION_TLS1_2);
201	#if defined(MBEDTLS_SSL_PROTO_TLS1_3)
202	    mbedtls_ssl_conf_max_tls_version(&ctx->cfg,
203	        MBEDTLS_SSL_VERSION_TLS1_3);
204	#else
205	    mbedtls_ssl_conf_max_tls_version(&ctx->cfg,
206	        MBEDTLS_SSL_VERSION_TLS1_2);
207	#endif
208	
209	#if defined(MBEDTLS_SSL_ALPN)
210	    static const char* alpn[] = { "http/1.1", NULL };
211	
212	    mbedtls_ssl_conf_alpn_protocols(&ctx->cfg, alpn);
213	#endif
214	
215	    mbedtls_ssl_conf_authmode(&ctx->cfg, MBEDTLS_SSL_VERIFY_OPTIONAL);
216	    mbedtls_ssl_conf_rng(&ctx->cfg, mbedtls_ctr_drbg_random,
217	        &ctx->ctr_drbg);
218	
219	    ret = mbedtls_ssl_setup(&ctx->ssl, &ctx->cfg);
220	    if (ret != 0) {
221	        return -EIO;
222	    }
223	
224	    mbedtls_ssl_set_hostname(&ctx->ssl, host);
225	    mbedtls_ssl_set_bio(&ctx->ssl, &ctx->net,
226	        mbedtls_net_send, mbedtls_net_recv, NULL);
227	
228	    while ((ret = mbedtls_ssl_handshake(&ctx->ssl)) != 0) {
229	        if (ret != MBEDTLS_ERR_SSL_WANT_READ
230	            && ret != MBEDTLS_ERR_SSL_WANT_WRITE) {
231	            syslog(LOG_ERR, "[%s] handshake: -0x%04x\n", TAG, -ret);
232	            return -EIO;
233	        }
234	    }
235	
236	    syslog(LOG_INFO, "[%s] TLS connected to %s:%s\n", TAG, host, port);
237	    return 0;
238	}
