309	/* ── WebSocket upgrade handshake ─────────────────────────────── */
310	
311	/* 2026-08-11 适配「流式语音识别大模型」（/api/v3/sauc/bigmodel）：
312	 * 鉴权从传统 Bearer;token 改为 X-Api-App-Key / X-Api-Access-Key /
313	 * X-Api-Resource-Id 三个请求头（见火山控制台 API 示例）。 */
314	static int ws_upgrade(asr_tls_ctx_t* ctx, const char* host,
315	    const char* path, const char* app_id,
316	    const char* token, const char* resource_id)
317	{
318	    /* Generate random 16-byte key, base64-encode it */
319	    unsigned char key_raw[16];
320	    unsigned char key_b64[32];
321	    size_t key_b64_len;
322	
323	    asr_entropy_func(NULL, key_raw, sizeof(key_raw));
324	    mbedtls_base64_encode(key_b64, sizeof(key_b64), &key_b64_len,
325	        key_raw, sizeof(key_raw));
326	
327	    char connect_id[ASR_UUID_LEN];
328	    generate_uuid(connect_id, sizeof(connect_id));
329	
330	    char req[1024];
331	    int n = snprintf(req, sizeof(req),
332	        "GET %s HTTP/1.1\r\n"
333	        "Host: %s\r\n"
334	        "Upgrade: websocket\r\n"
335	        "Connection: Upgrade\r\n"
336	        "Sec-WebSocket-Key: %.*s\r\n"
337	        "Sec-WebSocket-Version: 13\r\n"
338	        "X-Api-App-Key: %s\r\n"
339	        "X-Api-Access-Key: %s\r\n"
340	        "X-Api-Resource-Id: %s\r\n"
341	        "X-Api-Connect-Id: %s\r\n"
342	        "\r\n",
343	        path, host, (int)key_b64_len, key_b64,
344	        app_id, token, resource_id, connect_id);
345	
346	    if (n <= 0 || n >= (int)sizeof(req)) {
347	        return -EOVERFLOW;
348	    }
349	
350	    int ret = tls_write_all(ctx, (const unsigned char*)req, (size_t)n);
351	
352	    if (ret != 0) {
353	        return ret;
354	    }
355	
356	    /* Read HTTP 101 response */
357	    char resp[WS_BUF_SIZE];
358	    size_t rlen = 0;
359	
360	    while (rlen < sizeof(resp) - 1) {
361	        int r = mbedtls_ssl_read(&ctx->ssl,
362	            (unsigned char*)resp + rlen,
363	            sizeof(resp) - 1 - rlen);
364	
365	        if (r > 0) {
366	            rlen += (size_t)r;
367	            resp[rlen] = '\0';
368	            if (strstr(resp, "\r\n\r\n")) {
369	                break;
370	            }
371	        } else if (r == 0
372	            || r == MBEDTLS_ERR_SSL_PEER_CLOSE_NOTIFY) {
373	            return -ECONNRESET;
374	        } else if (r != MBEDTLS_ERR_SSL_WANT_READ) {
375	            return -EIO;
376	        }
377	    }
378	
379	    int status = 0;
380	
381	    if (sscanf(resp, "HTTP/1.1 %d", &status) != 1 || status != 101) {
382	        syslog(LOG_ERR, "[%s] WS upgrade failed: HTTP %d\n",
383	            TAG, status);
384	        return -EPROTO;
385	    }
386	
387	    syslog(LOG_INFO, "[%s] WebSocket upgrade OK\n", TAG);
388	    return 0;
389	}
