391	/* ── WebSocket frame send (client must mask) ─────────────────── */
392	
393	static int ws_send_binary(asr_tls_ctx_t* ctx,
394	    const unsigned char* payload, size_t plen)
395	{
396	    unsigned char hdr[14]; /* max WS header: 2 + 8 + 4 */
397	    size_t hdr_len = 0;
398	
399	    hdr[0] = WS_FIN_BIT | WS_OPCODE_BINARY;
400	
401	    if (plen < 126) {
402	        hdr[1] = WS_MASK_BIT | (unsigned char)plen;
403	        hdr_len = 2;
404	    } else if (plen <= 0xFFFF) {
405	        hdr[1] = WS_MASK_BIT | 126;
406	        hdr[2] = (unsigned char)(plen >> 8);
407	        hdr[3] = (unsigned char)(plen & 0xFF);
408	        hdr_len = 4;
409	    } else {
410	        hdr[1] = WS_MASK_BIT | 127;
411	        memset(hdr + 2, 0, 4); /* high 32 bits = 0 */
412	        hdr[6] = (unsigned char)((plen >> 24) & 0xFF);
413	        hdr[7] = (unsigned char)((plen >> 16) & 0xFF);
414	        hdr[8] = (unsigned char)((plen >> 8) & 0xFF);
415	        hdr[9] = (unsigned char)(plen & 0xFF);
416	        hdr_len = 10;
417	    }
418	
419	    /* Generate 4-byte mask key */
420	    unsigned char mask[WS_MASK_KEY_LEN];
421	
422	    asr_entropy_func(NULL, mask, WS_MASK_KEY_LEN);
423	    memcpy(hdr + hdr_len, mask, WS_MASK_KEY_LEN);
424	    hdr_len += WS_MASK_KEY_LEN;
425	
426	    /* Send header */
427	    int ret = tls_write_all(ctx, hdr, hdr_len);
428	
429	    if (ret != 0) {
430	        return ret;
431	    }
432	
433	    /* Mask and send payload in chunks to avoid large stack alloc */
434	    unsigned char chunk[1024];
435	    size_t sent = 0;
436	
437	    while (sent < plen) {
438	        size_t clen = plen - sent;
439	
440	        if (clen > sizeof(chunk)) {
441	            clen = sizeof(chunk);
442	        }
443	        for (size_t i = 0; i < clen; i++) {
444	            chunk[i] = payload[sent + i] ^ mask[(sent + i) % 4];
445	        }
446	        ret = tls_write_all(ctx, chunk, clen);
447	        if (ret != 0) {
448	            return ret;
449	        }
450	        sent += clen;
451	    }
452	
453	    return 0;
454	}
