456	/* ── WebSocket frame recv ────────────────────────────────────── */
457	
458	static int ws_recv_frame(asr_tls_ctx_t* ctx,
459	    unsigned char* buf, size_t cap,
460	    size_t* out_len, int* out_opcode)
461	{
462	    unsigned char hdr[2];
463	    int ret = tls_read_all(ctx, hdr, 2);
464	
465	    if (ret != 0) {
466	        return ret;
467	    }
468	
469	    *out_opcode = hdr[0] & 0x0F;
470	    int masked = (hdr[1] & WS_MASK_BIT) != 0;
471	    size_t plen = hdr[1] & 0x7F;
472	
473	    if (plen == 126) {
474	        unsigned char ext[2];
475	
476	        ret = tls_read_all(ctx, ext, 2);
477	        if (ret != 0) {
478	            return ret;
479	        }
480	        plen = ((size_t)ext[0] << 8) | ext[1];
481	    } else if (plen == 127) {
482	        unsigned char ext[8];
483	
484	        ret = tls_read_all(ctx, ext, 8);
485	        if (ret != 0) {
486	            return ret;
487	        }
488	        plen = ((size_t)ext[4] << 24) | ((size_t)ext[5] << 16)
489	            | ((size_t)ext[6] << 8) | ext[7];
490	    }
491	
492	    unsigned char mask[WS_MASK_KEY_LEN];
493	
494	    if (masked) {
495	        ret = tls_read_all(ctx, mask, WS_MASK_KEY_LEN);
496	        if (ret != 0) {
497	            return ret;
498	        }
499	    }
500	
501	    if (plen > cap) {
502	        syslog(LOG_ERR, "[%s] WS frame too large: %zu > %zu\n",
503	            TAG, plen, cap);
504	        return -EOVERFLOW;
505	    }
506	
507	    if (plen > 0) {
508	        ret = tls_read_all(ctx, buf, plen);
509	        if (ret != 0) {
510	            return ret;
511	        }
512	        if (masked) {
513	            for (size_t i = 0; i < plen; i++) {
514	                buf[i] ^= mask[i % 4];
515	            }
516	        }
517	    }
518	
519	    *out_len = plen;
520	    return 0;
521	}
