635	/* ── Receive and parse Volcengine server response ────────────── */
636	
637	/* Read a big-endian uint32 from buf at offset off. */
638	static uint32_t read_be32(const unsigned char* buf, size_t off)
639	{
640	    return ((uint32_t)buf[off] << 24)
641	        | ((uint32_t)buf[off + 1] << 16)
642	        | ((uint32_t)buf[off + 2] << 8)
643	        | (uint32_t)buf[off + 3];
644	}
645	
646	/* Receive one WS frame, unwrap Volcengine header, parse JSON.
647	 * Extracts result[0].text into text_out.
648	 * Returns: 1 = got final result, 0 = intermediate, negative = error
649	 *
650	 * Volcengine binary protocol layout varies by message type:
651	 *
652	 *   Normal response (msg_type 0x9):
653	 *     [4B header] [4B payload_size] [payload...]
654	 *
655	 *   Error response (msg_type 0xF):
656	 *     [4B header] [4B error_code] [4B error_msg_size] [error_msg...]
657	 */
658	static int recv_volc_response(asr_tls_ctx_t* ctx,
659	    char* text_out, size_t text_cap)
660	{
661	    unsigned char* buf = malloc(WS_BUF_SIZE);
662	
663	    if (!buf) {
664	        return -ENOMEM;
665	    }
666	
667	    size_t flen;
668	    int opcode;
669	    int ret = ws_recv_frame(ctx, buf, WS_BUF_SIZE, &flen, &opcode);
670	
671	    if (ret != 0) {
672	        free(buf);
673	        return ret;
674	    }
675	
676	    if (opcode == WS_OPCODE_CLOSE) {
677	        syslog(LOG_WARNING, "[%s] Server sent WS close\n", TAG);
678	        free(buf);
679	        return -ECONNRESET;
680	    }
681	
682	    /* Need at least Volcengine header (4 bytes minimum) */
683	    if (flen < 4) {
684	        syslog(LOG_ERR, "[%s] Frame too short: %zu\n", TAG, flen);
685	        free(buf);
686	        return -EPROTO;
687	    }
688	
689	    /* Parse Volcengine header */
690	    int hdr_units = buf[0] & 0x0F;
691	    size_t volc_hdr_len = (size_t)hdr_units * 4;
692	    unsigned char msg_type_byte = buf[1];
693	    unsigned char msg_type_nibble = (msg_type_byte >> 4) & 0x0F;
694	
695	    if (volc_hdr_len < 4 || flen < volc_hdr_len) {
696	        syslog(LOG_ERR,
697	            "[%s] Bad volc header: hdr_units=%d flen=%zu\n",
698	            TAG, hdr_units, flen);
699	        free(buf);
700	        return -EPROTO;
701	    }
702	
703	    /* ── Error response: special layout with error_code field ── */
704	    if (msg_type_nibble == 0x0F) {
705	        /* [4B hdr][4B error_code][4B msg_size][msg...] */
706	        if (flen < volc_hdr_len + 8) {
707	            syslog(LOG_ERR,
708	                "[%s] Error frame too short: %zu\n",
709	                TAG, flen);
710	            free(buf);
711	            return -EPROTO;
712	        }
713	
714	        uint32_t err_code = read_be32(buf, volc_hdr_len);
715	        uint32_t msg_size = read_be32(buf, volc_hdr_len + 4);
716	        size_t msg_off = volc_hdr_len + 8;
717	
718	        if (msg_off + msg_size > flen) {
719	            msg_size = (uint32_t)(flen - msg_off);
720	        }
721	
722	        /* NUL-terminate and log the error message */
723	        char errbuf[256];
724	        size_t cplen = msg_size;
725	
726	        if (cplen >= sizeof(errbuf)) {
727	            cplen = sizeof(errbuf) - 1;
728	        }
729	        memcpy(errbuf, buf + msg_off, cplen);
730	        errbuf[cplen] = '\0';
731	
732	        syslog(LOG_ERR,
733	            "[%s] Server error %lu: %s\n",
734	            TAG, (unsigned long)err_code, errbuf);
735	        free(buf);
736	        return -EIO;
737	    }
738	
739	    /* ── Normal response: [4B hdr][4B payload_size][payload] ── */
740	    if (flen < volc_hdr_len + 4) {
741	        syslog(LOG_ERR,
742	            "[%s] Frame too short for payload size: %zu\n",
743	            TAG, flen);
744	        free(buf);
745	        return -EPROTO;
746	    }
747	
748	    uint32_t payload_len = read_be32(buf, volc_hdr_len);
749	    size_t data_off = volc_hdr_len + 4;
750	
751	    if (data_off + payload_len > flen) {
752	        syslog(LOG_ERR,
753	            "[%s] Payload overrun: off=%zu + plen=%lu "
754	            "> flen=%zu\n",
755	            TAG, data_off, (unsigned long)payload_len, flen);
756	        free(buf);
757	        return -EPROTO;
758	    }
759	
760	    /* We only care about full_server_response (0x9) */
761	    if (msg_type_nibble != 0x09) {
762	        free(buf);
763	        return 0; /* skip unknown message types */
764	    }
765	
766	    /* Parse JSON payload */
767	    buf[data_off + payload_len] = '\0';
768	    cJSON* root = cJSON_Parse((char*)(buf + data_off));
769	
770	    free(buf);
771	    buf = NULL;
772	
773	    if (!root) {
774	        syslog(LOG_ERR, "[%s] Bad JSON in response\n", TAG);
775	        return -EPROTO;
776	    }
777	
778	    cJSON* code_j = cJSON_GetObjectItem(root, "code");
779	    int code = code_j ? (int)code_j->valuedouble : -1;
780	
781	    if (code != ASR_RESP_CODE_OK) {
782	        cJSON* msg_j = cJSON_GetObjectItem(root, "message");
783	
784	        syslog(LOG_ERR, "[%s] ASR error %d: %s\n", TAG, code,
785	            (msg_j && msg_j->valuestring)
786	                ? msg_j->valuestring
787	                : "unknown");
788	        cJSON_Delete(root);
789	        return -EIO;
790	    }
791	
792	    /* Extract result[0].text.
793	     * Volcengine streaming ASR sends multiple responses per session.
794	     * We maintain a "confirmed" offset: text_out[0..confirmed_len-1]
795	     * holds final utterances that must not be overwritten.
796	     * Intermediate results (seq >= 0) overwrite only the portion
797	     * after confirmed_len.  Final results (seq < 0) append and
798	     * advance confirmed_len. */
799	    cJSON* result = cJSON_GetObjectItem(root, "result");
800	
801	    /* Negative sequence means final response */
802	    cJSON* seq_j = cJSON_GetObjectItem(root, "sequence");
803	    int seq = seq_j ? (int)seq_j->valuedouble : 0;
804	
805	    if (cJSON_IsArray(result) && cJSON_GetArraySize(result) > 0) {
806	        cJSON* first = cJSON_GetArrayItem(result, 0);
807	        cJSON* txt = cJSON_GetObjectItem(first, "text");
808	
809	        if (txt && cJSON_IsString(txt) && txt->valuestring
810	            && txt->valuestring[0] != '\0') {
811	            static size_t confirmed_len;
812	            if (text_out[0] == '\0') {
813	                confirmed_len = 0;
814	            }
815	
816	            if (seq < 0) {
817	                /* Final: write after confirmed, then advance */
818	                size_t remain = text_cap - confirmed_len - 1;
819	                if (remain > 0) {
820	                    strncpy(text_out + confirmed_len,
821	                        txt->valuestring, remain);
822	                    text_out[text_cap - 1] = '\0';
823	                }
824	                confirmed_len = strlen(text_out);
825	            } else {
826	                /* Intermediate: overwrite only after confirmed */
827	                size_t remain = text_cap - confirmed_len - 1;
828	                if (remain > 0) {
829	                    strncpy(text_out + confirmed_len,
830	                        txt->valuestring, remain);
831	                    text_out[text_cap - 1] = '\0';
832	                }
833	            }
834	        }
835	    }
836	
837	    cJSON_Delete(root);
838	
839	    return (seq < 0) ? 1 : 0;
840	}
