584	#define TTS_MAX_CONSECUTIVE_TIMEOUTS 3
585	
586	    int chunks = 0;
587	    int consecutive_timeouts = 0;
588	    int err = 0;
589	
590	    while (1) {
591	        size_t flen;
592	        int opcode;
593	        int ret = ws_recv_frame(ctx, buf, WS_BUF_SIZE, &flen, &opcode);
594	
595	        if (ret != 0) {
596	            /* Timeout after audio started: retry up to N times to
597	             * tolerate transient stalls.  Only declare EOF after
598	             * consecutive timeouts exceed the threshold (~1.5s). */
599	            if (chunks > 0 && ret == -ETIMEDOUT) {
600	                consecutive_timeouts++;
601	                if (consecutive_timeouts < TTS_MAX_CONSECUTIVE_TIMEOUTS) {
602	                    syslog(LOG_DEBUG,
603	                        "[%s] recv timeout %d/%d, retrying\n",
604	                        TAG, consecutive_timeouts,
605	                        TTS_MAX_CONSECUTIVE_TIMEOUTS);
606	                    continue;
607	                }
608	                syslog(LOG_INFO,
609	                    "[%s] recv ended after %d chunks "
610	                    "(%d consecutive timeouts)\n",
611	                    TAG, chunks, consecutive_timeouts);
612	                break;
613	            }
614	
615	            /* Peer close after audio started is normal EOF. */
616	            if (chunks > 0 && ret == -ECONNRESET) {
617	                syslog(LOG_INFO, "[%s] recv ended after %d chunks (rc=%d)\n",
618	                    TAG, chunks, ret);
619	                break;
620	            }
621	
622	            syslog(LOG_ERR, "[%s] recv error before any audio: %d\n", TAG, ret);
623	            err = ret;
624	            break;
625	        }
626	
627	        /* Any successful frame resets the timeout counter. */
628	        consecutive_timeouts = 0;
629	
630	        if (opcode == WS_OPCODE_CLOSE) {
631	            syslog(LOG_INFO, "[%s] server closed WS\n", TAG);
632	            break;
633	        }
634	
635	        if (flen < 4) {
636	            continue;
637	        }
638	
639	        unsigned char msg_type = buf[1] & 0xF0;
640	        unsigned char msg_flags = buf[1] & 0x0F;
641	        size_t volc_hdr_len = (size_t)(buf[0] & 0x0F) * 4;
642	
643	
644	        if (volc_hdr_len < 4 || flen < volc_hdr_len) {
645	            continue;
646	        }
647	
648	        /* Error response */
649	        if (msg_type == VOLC_MSG_ERROR) {
650	            uint32_t code = 0;
651	
652	            if (flen >= volc_hdr_len + 4) {
653	                code = ((uint32_t)buf[volc_hdr_len] << 24) | ((uint32_t)buf[volc_hdr_len + 1] << 16) | ((uint32_t)buf[volc_hdr_len + 2] << 8) | (uint32_t)buf[volc_hdr_len + 3];
654	            }
655	
656	            syslog(LOG_ERR, "[%s] server error: %lu\n", TAG, (unsigned long)code);
657	            err = -EIO;
658	            break;
659	        }
660	
661	        /* Frontend response (e.g. duration info) — signals end of audio
662	         * when it arrives after audio chunks have been received. */
663	        if (msg_type == VOLC_MSG_FRONTEND) {
664	            if (chunks > 0) {
665	                break; /* All audio delivered, frontend is the epilogue */
666	            }
667	            continue;
668	        }
669	
670	        /* Audio-only response (0xB) */
671	        if (msg_type == VOLC_MSG_AUDIO_RESP) {
672	            /* flags: 0=ack(no audio), 1+=has audio data */
673	            if (msg_flags == 0) {
674	                continue; /* ACK, no audio data */
675	            }
676	
677	            /* After volc header: 4-byte sequence (signed) + 4-byte payload_size */
678	            size_t audio_off = volc_hdr_len + 8;
679	
680	            if (flen <= audio_off) {
681	                continue;
682	            }
683	
684	            /* Extract sequence as signed 32-bit (big-endian).
685	             * Per Volcengine binary protocol: sequence < 0 means last frame. */
686	            int32_t seq = (int32_t)(
687	                ((uint32_t)buf[volc_hdr_len] << 24) |
688	                ((uint32_t)buf[volc_hdr_len + 1] << 16) |
689	                ((uint32_t)buf[volc_hdr_len + 2] << 8) |
690	                (uint32_t)buf[volc_hdr_len + 3]);
691	
692	            unsigned char* pcm = buf + audio_off;
693	            size_t pcm_len = flen - audio_off;
694	
695	            cb(pcm, pcm_len, 0, user_data);
696	            chunks++;
697	
698	            /* After first chunk, tighten recv timeout so we detect
699	             * end-of-stream quickly (server may not send close frame). */
700	            if (chunks == 1 && ctx->net.fd >= 0) {
701	                struct timeval tv = { .tv_sec = 0, .tv_usec = 500000 };
702	                if (setsockopt(ctx->net.fd, SOL_SOCKET, SO_RCVTIMEO,
703	                        &tv, sizeof(tv)) < 0) {
704	                    syslog(LOG_WARNING,
705	                        "[%s] setsockopt SO_RCVTIMEO failed: %d\n",
706	                        TAG, errno);
707	                }
708	            }
709	
710	            /* sequence < 0 = last audio frame */
711	            if (seq < 0) {
712	                break;
713	            }
714	        }
715	    }
716	
717	    free(buf);
718	
719	    if (chunks > 0 && err == 0) {
720	        cb(NULL, 0, 1, user_data);
721	    }
722	
723	    syslog(LOG_INFO, "[%s] %d audio chunks delivered\n", TAG, chunks);
724	
725	    if (chunks == 0 && err == 0) {
726	        return -EPROTO;
727	    }
728	
729	    return err;
730	}
