243	/* Connect to the local ai_agent (127.0.0.1:28789) and complete the WS
244	 * upgrade handshake.  Returns connected fd on success, -1 on failure.
245	 * P53: extracted from ai_worker so the voice control path reuses it. */
246	static int ai_ws_connect(void)
247	{
248	    int fd = socket(AF_INET, SOCK_STREAM, 0);
249	    if (fd < 0)
250	        return -1;
251	
252	    struct sockaddr_in sa;
253	    memset(&sa, 0, sizeof(sa));
254	    sa.sin_family = AF_INET;
255	    sa.sin_port = htons(AI_WS_PORT);
256	    sa.sin_addr.s_addr = inet_addr(AI_WS_HOST);
257	    if (connect(fd, (struct sockaddr *)&sa, sizeof(sa)) < 0)
258	        {
259	            close(fd);
260	            return -1;
261	        }
262	
263	    /* P53 调优（AIYOUHUA A1）：30s 收包超时，防止 agent 不回复时永久阻塞 */
264	    struct timeval tv;
265	    tv.tv_sec  = 30;
266	    tv.tv_usec = 0;
267	    setsockopt(fd, SOL_SOCKET, SO_RCVTIMEO, &tv, sizeof(tv));
268	
269	    /* HTTP Upgrade handshake */
270	    unsigned char rnd[16];
271	    for (int i = 0; i < 16; i++)
272	        rnd[i] = (unsigned char)(rand() & 0xFF);
273	    char key_b64[64];
274	    b64_encode(rnd, 16, key_b64, sizeof(key_b64));
275	    char req[512];
276	    snprintf(req, sizeof(req),
277	             "GET / HTTP/1.1\r\n"
278	             "Host: %s:%d\r\n"
279	             "Upgrade: websocket\r\n"
280	             "Connection: Upgrade\r\n"
281	             "Sec-WebSocket-Key: %s\r\n"
282	             "Sec-WebSocket-Version: 13\r\n"
283	             "\r\n",
284	             AI_WS_HOST, AI_WS_PORT, key_b64);
285	    if (send(fd, req, strlen(req), 0) != (int)strlen(req))
286	        {
287	            close(fd);
288	            return -1;
289	        }
290	
291	    /* read handshake response until header end */
292	    char hb[512];
293	    int total = 0;
294	    while (total < (int)sizeof(hb) - 1)
295	        {
296	            int n = recv(fd, hb + total, sizeof(hb) - 1 - total, 0);
297	            if (n <= 0)
298	                {
299	                    close(fd);
300	                    return -1;
301	                }
302	            total += n;
303	            hb[total] = '\0';
304	            if (strstr(hb, "\r\n\r\n"))
305	                break;
306	        }
307	    if (!strstr(hb, "101"))
308	        {
309	            close(fd);
310	            return -1;   /* not a websocket upgrade */
311	        }
312	    return fd;
313	}
