315	static void *ai_worker(void *arg)
316	{
317	    (void)arg;
318	    int fd = -1;
319	    /* P53 调优：buf 改 static——AI_RESP_MAX 1024→4096 后栈上 4KB 缓冲可能
320	     * 压爆默认 pthread 栈；worker 受 g_ai_busy 保护单实例，static 无并发风险。 */
321	    static char buf[AI_RESP_MAX];
322	
323	    g_ai_ok = 0;
324	    g_ai_done = 0;
325	
326	    fd = ai_ws_connect();
327	    if (fd < 0)
328	        goto fail;
329	
330	    /* 3. Send question as JSON message frame */
331	    {
332	        /* 2026-08-11 调优：用户输入 JSON 转义——原实现 %s 直接拼入 JSON，
333	         * 文本含 " 或 \ 时协议损坏，ws_server cJSON_Parse 失败丢消息，
334	         * UI 盲等 30s。转义后任意文本均可安全传输。 */
335	        char esc[AI_REQ_MAX * 2 + 1];
336	        json_escape(g_ai_req, esc, sizeof(esc));
337	        char json[sizeof(esc) + 64];
338	        snprintf(json, sizeof(json),
339	                 "{\"type\":\"message\",\"content\":\"%s\",\"chat_id\":\"ui\"}",
340	                 esc);
341	        if (ws_send_text(fd, json) < 0)
342	            goto fail;
343	    }
344	
345	    /* 4. Read frames until a response containing "content" */
346	    for (int spins = 0; spins < 200; spins++)
347	        {
348	            int n = ws_recv_text(fd, buf, sizeof(buf));
349	            if (n <= 0)
350	                goto fail;
351	            if (strstr(buf, "\"type\":\"response\""))
352	                {
353	                    extract_content(buf, g_ai_resp, sizeof(g_ai_resp));
354	                    if (g_ai_resp[0] != '\0')
355	                        {
356	                            g_ai_ok = 1;
357	                            break;
358	                        }
359	                }
360	        }
361	
362	    close(fd);
363	    g_ai_busy = 0;
364	    g_ai_done = 1;
365	    return NULL;
366	
367	fail:
368	    if (fd >= 0)
369	        close(fd);
370	    /* 2026-08-11 调优：失败时给出错误提示而非静默空回复——原实现
371	     * g_ai_ok=0 → dm_ai_poll 返回空串 → UI 回复区被清空且无任何说明。
372	     * 现写入错误信息（g_ai_ok=1 使 poll 正常返回该文本）。 */
373	    if (!g_ai_ok)
374	        {
375	            snprintf(g_ai_resp, sizeof(g_ai_resp),
376	                     "⚠️ AI 不可用：agent 未启动或连接失败/超时");
377	            g_ai_ok = 1;
378	        }
379	    g_ai_busy = 0;
380	    g_ai_done = 1;
381	    return NULL;
382	}
