128	/* Receive one text frame (server → client, unmasked). Returns payload len,
129	 * -1 on error/close. */
130	static int ws_recv_text(int fd, char *out, int outcap)
131	{
132	    unsigned char b0, b1;
133	    if (recv(fd, &b0, 1, MSG_WAITALL) != 1)
134	        return -1;
135	    if (recv(fd, &b1, 1, MSG_WAITALL) != 1)
136	        return -1;
137	
138	    int opcode = b0 & 0x0F;
139	    size_t plen = b1 & 0x7F;
140	    int masked = (b1 & 0x80) != 0;
141	
142	    if (plen == 126)
143	        {
144	            unsigned char ext[2];
145	            if (recv(fd, ext, 2, MSG_WAITALL) != 2)
146	                return -1;
147	            plen = (ext[0] << 8) | ext[1];
148	        }
149	    else if (plen == 127)
150	        {
151	            unsigned char ext[8];
152	            if (recv(fd, ext, 8, MSG_WAITALL) != 8)
153	                return -1;
154	            plen = 0;
155	            for (int i = 0; i < 8; i++)
156	                plen = (plen << 8) | ext[i];
157	        }
158	
159	    unsigned char mask[4] = { 0, 0, 0, 0 };
160	    if (masked)
161	        {
162	            if (recv(fd, mask, 4, MSG_WAITALL) != 4)
163	                return -1;
164	        }
165	
166	    if (opcode == 0x8)                  /* close */
167	        return -1;
168	    if (opcode == 0x9)                  /* ping → pong */
169	        {
170	            unsigned char pong[2] = { 0x8A, 0x00 };
171	            send(fd, pong, 2, 0);
172	            return 0;
173	        }
174	    if (opcode != 0x1)                  /* ignore non-text */
175	        {
176	            unsigned char discard[256];
177	            size_t left = plen;
178	            while (left > 0)
179	                {
180	                    size_t todo = left > sizeof(discard) ?
181	                                  sizeof(discard) : left;
182	                    if (recv(fd, discard, todo, MSG_WAITALL) != (int)todo)
183	                        return -1;
184	                    left -= todo;
185	                }
186	            return 0;
187	        }
188	
189	    if ((int)plen >= outcap)
190	        plen = outcap - 1;
191	    size_t got = 0;
192	    while (got < plen)
193	        {
194	            int n = recv(fd, out + got, plen - got, 0);
195	            if (n <= 0)
196	                return -1;
197	            got += n;
198	        }
199	    for (size_t i = 0; i < got; i++)
200	        out[i] ^= mask[i & 3];
201	    out[got] = '\0';
202	    return (int)got;
203	}
