/* 2026-08-12 修复（上板 json dump 实锤）：火山大模型接口的
 * 成功响应**没有 code 字段**（实测 {"audio_info":{...},
 * "result":{"text":"..."}}，无 header/code/message 包装），
 * 原实现 code_j==NULL → code=-1 误报 "ASR error -1: unknown"
 * 且直接 return -EIO 丢弃结果。改为：无 code 字段 = 成功；
 * 仅当显式返回 code 且 != 1000 才报错。 */
cJSON* header = cJSON_GetObjectItem(root, "header");
cJSON* code_j = cJSON_GetObjectItem(root, "code");
if (!code_j && header) {
    code_j = cJSON_GetObjectItem(header, "code");
}

if (code_j) {
    int code = (int)code_j->valuedouble;

    if (code != ASR_RESP_CODE_OK) {
        cJSON* msg_j = cJSON_GetObjectItem(root, "message");
        if (!msg_j && header) {
            msg_j = cJSON_GetObjectItem(header, "message");
        }

        /* 诊断增强：报错时转储响应 JSON 前 256B，便于上板核对结构 */
        char* dump = cJSON_PrintUnformatted(root);
        syslog(LOG_ERR, "[%s] ASR error %d: %s (json=%.256s)\n",
            TAG, code,
            (msg_j && msg_j->valuestring)
                ? msg_j->valuestring
                : "unknown",
            dump ? dump : "(null)");
        if (dump) {
            free(dump);
        }
        cJSON_Delete(root);
        return -EIO;
    }
}

