/* Negative sequence means final response.
 * 2026-08-12 修复：优先用帧头二进制 seq（有符号，负值=最终响应，
 * 与 TTS 侧 recv_tts_audio 的 seq<0 判定同约定）；JSON 顶层
 * "sequence" 字段兜底。原实现只看 JSON（可能缺失）导致永远
 * 不判最终。 */
cJSON* seq_j = cJSON_GetObjectItem(root, "sequence");
if (!seq_j && header) {
    seq_j = cJSON_GetObjectItem(header, "sequence");
}
if (!seq_j && payload) {
    seq_j = cJSON_GetObjectItem(payload, "sequence");
}
int json_seq = (seq_j && cJSON_IsNumber(seq_j))
    ? (int)seq_j->valuedouble : 0;
int seq = (resp_seq < 0) ? resp_seq : json_seq;

/* 2026-08-12 修复（上板 json dump 实锤）：大模型接口的 result 是
 * **对象** {"text":"...","additions":{...}}，不是数组。原实现只
 * 走 result[0].text → 永远取不到文本。兼容三种形态：
 *   对象 result.text / 数组 result[0].text / payload.text 兜底。 */
cJSON* txt = NULL;
if (result) {
    if (cJSON_IsObject(result)) {
        txt = cJSON_GetObjectItem(result, "text");
    } else if (cJSON_IsArray(result)
               && cJSON_GetArraySize(result) > 0) {
        cJSON* first = cJSON_GetArrayItem(result, 0);
        txt = cJSON_GetObjectItem(first, "text");
    }
}
if (!txt && payload) {
    txt = cJSON_GetObjectItem(payload, "text");
}

if (txt && cJSON_IsString(txt) && txt->valuestring
    && txt->valuestring[0] != '\0') {
    static size_t confirmed_len;
    if (text_out[0] == '\0') {
        confirmed_len = 0;
    }

    if (seq < 0) {
        /* Final: write after confirmed, then advance */
        size_t remain = text_cap - confirmed_len - 1;
        if (remain > 0) {
            strncpy(text_out + confirmed_len,
                txt->valuestring, remain);
            text_out[text_cap - 1] = '\0';
        }
        confirmed_len = strlen(text_out);
    } else {
        /* Intermediate: overwrite only after confirmed */
        size_t remain = text_cap - confirmed_len - 1;
        if (remain > 0) {
            strncpy(text_out + confirmed_len,
                txt->valuestring, remain);
            text_out[text_cap - 1] = '\0';
        }
    }
}

