/* 2026-08-11 P56+ 修复：集成 MIC（MICIN1P/MICIN1N + MBIAS → ADC1）。
 * codec 默认 MIC_PGA_EN（MIC1 input switch）关闭 → sunxi_get_adc_ch()
 * 返回 -1 → capture hw_params 报 "only support 1~3 channel" -22。
 * 先经 snd_ctl 打开 ADC1 MIC 通路 + 增益（参考 HAL aloop 测试写法）。
 * 2026-08-12 提高增益：上板实测轻声录音 peak 仅 200± → 服务器 VAD
 * 判无语音（text:"" / duration:0）。MIC1 gain volume mask 0x1F（0~31，
 * codec 默认 .mic1gain=0x1f），从 19 提到 31（最大 PGA 增益）。 */
snd_ctl_set("audiocodec", "MIC1 gain volume", 31);
snd_ctl_set("audiocodec", "MIC1 input switch", 1);
snd_ctl_set("audiocodec", "MIC2 input switch", 0);
snd_ctl_set("audiocodec", "MIC3 input switch", 0);

